Contract ProcessSaleService::enterItem(barcode:Integer,quantity:Integer): Boolean {

            precondition:
          CurrentSale.oclIsUndefined() = false and CurrentSale.IsComplete = false and quantity > 0 and Item.allInstances()->exists(i: Item | i.Barcode = barcode and i.StockNumber > 0 and quantity <= i.StockNumber)

            postcondition:
          result = true and Item.allInstances()->exists(i: Item | i.Barcode = barcode and i.StockNumber@pre > 0 and quantity <= i.StockNumber@pre and i.StockNumber = i.StockNumber@pre - quantity and SalesLineItem.allInstances()->exists(sl: SalesLineItem | sl.oclIsNew() = true and sl.Quantity = quantity and sl.Subamount = i.Price * quantity and sl.BelongedSale = CurrentSale and sl.BelongedItem = i and CurrentSale.ContainedSalesLine->includes(sl) and CurrentSaleLine = sl and CurrentSale.ContainedSalesLine@pre->excludes(sl)))

        }
